import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.BxL9yGGP.js";const u=JSON.parse('{"title":"Metrics","description":"","frontmatter":{},"headers":[],"relativePath":"metrics.md","filePath":"metrics.md","lastUpdated":null}'),r={name:"metrics.md"};function o(n,e,d,l,c,p){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="metrics" tabindex="-1">Metrics <a class="header-anchor" href="#metrics" aria-label="Permalink to &quot;Metrics&quot;">​</a></h1><p>The <strong>Metrics</strong> desktop window separates three different questions that must not be collapsed into one score:</p><ul><li><strong>technical reliability</strong>: successful Task Router responses divided by all recorded Task Router calls;</li><li><strong>reviewed accuracy</strong>: operator-accepted decisions divided by all reviewed decisions;</li><li><strong>review coverage</strong>: reviewed decisions divided by all router decisions in the selected period.</li></ul><p>Task completion is not treated as proof that the initial routing was correct. An operator records explicit <code>accepted</code>, <code>corrected</code>, or <code>rejected</code> feedback. Corrections are schema-constrained, stored in <code>task_router_reviews</code>, mirrored as <code>task.router_reviewed</code> events, and audited.</p><p>Reviews can correct action, category, priority, severity, suggested owner and whether operator attention is required. The operator note is stored separately from the model decision and remains part of the canonical review. Completing a task is never treated as implicit approval of its routing decision.</p><h2 id="ai-manager-operations" tabindex="-1">AI manager operations <a class="header-anchor" href="#ai-manager-operations" aria-label="Permalink to &quot;AI manager operations&quot;">​</a></h2><p>Calls routed through the inventory-declared AI manager record only normalized operational telemetry, never prompts or raw model output:</p><ul><li>effective provider and model;</li><li>local/fallback outcome and sanitized failure category;</li><li>queue wait and inference latency;</li><li>prompt, schema and model versions;</li><li>token usage already covered by the canonical usage record.</li></ul><p>The API process permits one llama.cpp inference at a time. This matches the single slot on <code>ai-host</code>; the recorded queue wait makes saturation visible. The Metrics window reports local response rate, OpenAI fallback rate, schema errors, timeouts, average and p95 latency, and effective model distribution. Historical rows remain valid but have no invented latency or version metadata.</p><h2 id="ai-delivery" tabindex="-1">AI delivery <a class="header-anchor" href="#ai-delivery" aria-label="Permalink to &quot;AI delivery&quot;">​</a></h2><p>The <strong>AI Delivery</strong> desktop window presents conversation turns separately from Task Router quality. One delivery row represents one completed or failed conversation turn, not one provider request: a turn that uses a governed tool can contain two model decisions, and its recorded model-path latency is the sum of those measured decisions. The window reports successful and failed turns, fallback rate, average/p95 path latency, effective provider/model distribution, and the latest 20 normalized delivery records.</p><p>Delivery rows classify the route as <strong>Free chat</strong>, <strong>Operations shortcut</strong>, or <strong>Operations question</strong>. Free chat has no tool contract and uses one model decision. A fixed shortcut executes one declared summary tool and then one model decision. Only an arbitrary Operations question can require the two-pass model → tool → model path. Historical rows without route schema metadata remain explicitly classified as <strong>Legacy / unclassified</strong> rather than being attributed to a new route.</p><p>Provider failures are recorded with sanitized categories and fallback metadata. Prompts, conversation text, raw provider responses, credentials and tool payloads are never copied into <code>llm_usage_events</code> or the delivery ledger.</p><p>These reviews and measurements are operational application state. This milestone does not export a dataset or perform online training.</p><h2 id="usage-and-attributed-cost" tabindex="-1">Usage and attributed cost <a class="header-anchor" href="#usage-and-attributed-cost" aria-label="Permalink to &quot;Usage and attributed cost&quot;">​</a></h2><p><code>llm_usage_events</code> stores normalized usage for:</p><ul><li><code>task_router</code>;</li><li><code>incident_matcher</code>;</li><li><code>conversation</code>.</li></ul><p>Each row records the model, status, input/cached/output/reasoning token counts, the price snapshot used, attributed USD cost, source reference and optional task. Historical events and conversation messages are backfilled idempotently at API startup. Missing historical metering remains missing and reduces the displayed coverage; it is never replaced with an invented value.</p><p>The built-in <code>gpt-5.6-luna</code> standard price snapshot is dated 2026-07-09: $1.00/M input, $0.10/M cached input and $6.00/M output. See the <a href="https://developers.openai.com/api/docs/models/gpt-5.6-luna" target="_blank" rel="noreferrer">official model page</a>.</p><p>The number in this window is <strong>attributed cost</strong>, calculated from response usage. It is not labelled as billed cost. Financial reconciliation requires a separate, server-only integration with OpenAI&#39;s organization Costs endpoint and an Admin API key; that integration is intentionally not enabled in this milestone.</p><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/luna/metrics?days=30</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Returns the summary, per-component usage, AI delivery metrics, router review metrics, auto-investigate policy outcomes and a recent unreviewed queue.</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">POST</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/luna/tasks/{task_id}/review</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;verdict&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;corrected&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;corrections&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;suggested_owner&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;fixer&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>All endpoints require an authenticated session; review writes also require the normal CSRF token. No infrastructure action or tool execution is exposed.</p>`,25)])])}const m=t(r,[["render",o]]);export{u as __pageData,m as default};
